SELECT * FROM (
    SELECT b.BOOK_HISTORY_ID, b.MEMBERS_ID, b.BOOKS_ID, 
           b.LOAN_DATE, b.DUE_DATE, b.RETURNED_DATE, b.STATUS, 
           bk.TITLE, bk.IMAGE_LINK,
           ROWNUM AS rnum
    FROM (
        SELECT bh.BOOK_HISTORY_ID, bh.MEMBERS_ID, bh.BOOKS_ID, 
               bh.LOAN_DATE, bh.DUE_DATE, bh.RETURNED_DATE, bh.STATUS
        FROM BOOK_HISTORY bh
        WHERE bh.MEMBERS_ID = #{membersId}
        ORDER BY bh.LOAN_DATE DESC
    ) b
    JOIN (
        SELECT BOOKS_ID, TITLE, IMAGE_LINK
        FROM BOOKS
    ) bk ON b.BOOKS_ID = bk.BOOKS_ID
    WHERE ROWNUM <= #{endRow}
)
WHERE rnum > #{startRow}

        SELECT * FROM BOOK_HISTORY 
        WHERE MEMBERS_ID = #{membersId} 
	        AND BOOKS_ID = #{booksId} 
	        AND RETURND_DATE IS NULL

